        public static StreetPoint[] Get(string from,string to,StreetSurface surface)
        {
            if(!Paths.TryGetValue(from+"|"+to+"|"+surface,out var data))return null;
            var pairs=data.Split(' ');var result=new StreetPoint[pairs.Length];
            for(int i=0;i<pairs.Length;i++){var xy=pairs[i].Split(',');result[i]=new StreetPoint(float.Parse(xy[0],CultureInfo.InvariantCulture),float.Parse(xy[1],CultureInfo.InvariantCulture));}
            return result;
        }
    }
